const candleResponse = $('get candles').first().json;
const portfolioResponse = $('get portfolio').first().json;

const candles = candleResponse.candles || [];

if (candles.length < 26) {
  return [{
    json: {
      error: true,
      message: `Insufficient candles (${candles.length}/26).`
    }
  }];
}

const closes = candles.map(c => Number(c.close));
const volumes = candles.map(c => Number(c.volume || 0));
const currentPrice = closes[closes.length - 1];

function calcEMA(data, period) {
  const k = 2 / (period + 1);
  let ema = data[0];
  for (let i = 1; i < data.length; i++) {
    ema = data[i] * k + ema * (1 - k);
  }
  return ema;
}

const ema9 = calcEMA(closes, 9);
const ema21 = calcEMA(closes, 21);
const ema12 = calcEMA(closes, 12);
const ema26 = calcEMA(closes, 26);
const macdLine = ema12 - ema26;

let gains = 0, losses = 0;
for (let i = closes.length - 14; i < closes.length; i++) {
  const diff = closes[i] - closes[i - 1];
  if (diff >= 0) gains += diff;
  else losses -= diff;
}
const rs = (gains / 14) / ((losses / 14) || 1);
const rsi14 = 100 - (100 / (1 + rs));

const currentVol = volumes[volumes.length - 1];
const avgVol = volumes.slice(-10).reduce((a, b) => a + b, 0) / 10;

const symbol = "COMPANY_X";
const positions = portfolioResponse.positions || [];
const activePos = positions.find(p => p.symbol === symbol && Number(p.quantity) > 0);

return [{
  json: {
    error: false,
    symbol,
    currentPrice: Number(currentPrice.toFixed(2)),
    ema9: Number(ema9.toFixed(2)),
    ema21: Number(ema21.toFixed(2)),
    macd: Number(macdLine.toFixed(4)),
    rsi14: Number(rsi14.toFixed(2)),
    volumeStatus: currentVol > avgVol * 1.3 ? 'HIGH' : 'NORMAL',
    cashBalance: Number(portfolioResponse.cashBalance ?? 100000),
    hasOpenPosition: !!activePos,
    openQuantity: activePos ? Number(activePos.quantity) : 0,
    avgEntryPrice: activePos ? Number(activePos.avgPrice) : 0,
    unrealizedPnL: activePos ? Number(activePos.unrealizedPnL ?? 0) : 0
  }
}];

