const data = $input.first().json;

const initialCapital = 100000;
const cashBalance = Number(data.cashBalance ?? initialCapital);
const positions = data.positions || [];
const trades = data.trades || data.tradeHistory || [];

// Open positions ki current value aur unrealized PnL calculate karo
let positionsValue = 0;
let unrealizedPnL = 0;
let activeHoldingsText = "None";

if (positions.length > 0) {
  const activeList = positions.filter(p => Number(p.quantity) > 0);
  if (activeList.length > 0) {
    activeHoldingsText = activeList.map(p => {
      const qty = Number(p.quantity);
      const avg = Number(p.avgPrice || 0);
      const curr = Number(p.currentPrice || avg);
      const pnl = Number(p.unrealizedPnL ?? ((curr - avg) * qty));
      positionsValue += curr * qty;
      unrealizedPnL += pnl;
      return `${p.symbol}: ${qty} qty @ $${avg.toFixed(2)} (PnL: $${pnl.toFixed(2)})`;
    }).join("\n");
  }
}

const totalEquity = Number(data.totalEquity ?? (cashBalance + positionsValue));
const netPnL = totalEquity - initialCapital;
const returnPct = (netPnL / initialCapital) * 100;

// Win rate calculation (agar closed trades array available hai)
let totalTrades = trades.length;
let winningTrades = trades.filter(t => Number(t.realizedPnL || t.pnl || 0) > 0).length;
let closedTrades = trades.filter(t => t.side === 'SELL' || Number(t.realizedPnL || 0) !== 0).length;
let winRate = closedTrades > 0 ? ((winningTrades / closedTrades) * 100).toFixed(1) : "N/A (Holding)";

return [{
  json: {
    date: new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata' }),
    totalEquity: totalEquity.toFixed(2),
    cashBalance: cashBalance.toFixed(2),
    netPnL: (netPnL >= 0 ? "+" : "") + netPnL.toFixed(2),
    returnPct: (returnPct >= 0 ? "+" : "") + returnPct.toFixed(2) + "%",
    unrealizedPnL: (unrealizedPnL >= 0 ? "+" : "") + unrealizedPnL.toFixed(2),
    totalTrades,
    winRate,
    activeHoldingsText,
    statusEmoji: netPnL >= 0 ? "📈" : "📉"
  }
}];

const newsItems = $input.all().slice(0, 5);

const headlines = newsItems.map((item, idx) => {
  return `${idx + 1}. ${item.json.title || "No Title"}`;
}).join("\n");

return [{
  json: {
    latestHeadlines: headlines || "No fresh market news available."
  }
}];
